// Root coordinates are the ball centre. The visible sprite diameter
// includes the atlas-cell visual-size correction from the CSS.
// 13% of that diameter remains above the Hero's bottom edge at dock.
const renderedDiameter = activeProfile.tileSize * activeProfile.endScale * 1.1327434;
const dockY = sliderRect.bottom + renderedDiameter * (.5 - .13)
    + (scrollPosition - transitionStart);

// First-phase destination must equal the fixed viewport dock position;
// calculate it from the actual Hero height to avoid an endpoint jump.
const desktopDock = desktopScene.matches && venuesV3;
const heroHeight = Math.max(1, slider.getBoundingClientRect().height);
const renderedDiameter = activeProfile.tileSize * activeProfile.endScale * 1.1327434;
const endY = desktopDock
    ? (heroHeight + renderedDiameter * (.5 - .13)) * 1000 / heroHeight
    : activeProfile.to[1];
const y = activeProfile.from[1] + (endY - activeProfile.from[1]) * travel;
